#include <vector>
#include <algorithm>
#include <unordered_map>

int leastInterval(std::vector<char>& tasks, int n) {
    std::unordered_map<char, int> task_freq;
    for (char task : tasks) {
        task_freq[task]++;
    }

    int max_f = 0;
    for (auto entry : task_freq) {
        max_f = std::max(max_f, entry.second);
    }

    int max_count = 0;
    for (auto entry : task_freq) {
        if (entry.second == max_f) {
            max_count++;
        }
    }

