    for (int i = 0; i < n; ++i) {
        int target = n - i - 1;
        int current_row = i;
        while (current_row < n && row_zeros[current_row] < target) {
            current_row++;
        }
        if (current_row == n) {
            return -1;
        }
        steps += current_row - i;
        std::swap(row_zeros[i], row_zeros[current_row]);
    }
    return steps;
}

